    "id": "zi_2729134",
    "source": "zadania.info",
    "source_id": "2729134",
    "source_url": "https://zadania.info/d1/2729134",
    "year": null,
    "exam_source": "",
    "difficulty": "sredni",
    "category": "Inne",
    "statement": "Promień okręgu o równaniu [2 2 x + y − 12x + 33 = 0]",
